protected void deleteDataByQuery(DEV_CleanupTaskSettingsQuery _settingsQuery)
{
    DEVIntegMessageTable integMessageTable;
    boolean              continueDelete;

    QueryRun localQueryRun = this.initQueryRun(_settingsQuery);

    while (localQueryRun.next())
    {
        integMessageTable = localQueryRun.get(tableNum(DEVIntegMessageTable));

        DataAreaId dataAreaId = this.getValidCompany(integMessageTable.CompanyId);

        changecompany(dataAreaId)
        {
            continueDelete = this.deleteRecord(integMessageTable);
        }

        if (!continueDelete)
        {
            break;
        }
    }
}

public DEV_CleanUpTaskName getTaskName()
{
    ;
    return 'DEVIntegMessageTable table cleanup';
}

protected void updateQuery(Query _query, DEV_CleanupTaskSettingsQuery _settings)
{
    TransDateTime           cleanupdDateTime = _settings.getCleanupDateTime();
    QueryBuildDataSource    qbds = _query.dataSourceNo(1);
    QueryBuildRange         qbr;

    qbr = SysQuery::findOrCreateRange(qbds, fieldNum(DEVIntegMessageTable, CreatedDateTime));
    qbr.value(SysQuery::range(dateNull(), cleanupdDateTime));
}

public Query getQuery()
{
    Query ret = new Query();

    ret.allowCrossCompany(true);
    ret.addDataSource(tableNum(DEVIntegMessageTable));

    return ret;
}
